package render

import (
	"bytes"
	"crypto/sha256"
	"fmt"
	"strings"
	"testing"

	"github.com/HHSoftSoftware/hhsoft-pc-tester/internal/app"
	"github.com/HHSoftSoftware/hhsoft-pc-tester/internal/report"
)

func TestRetestPreservesIndependentLegacyViewGoldens(t *testing.T) {
	// Fixed minimal v1 fixtures independently encoded from the historical
	// template and PDF wire contract, not generated by the changed renderers.
	payload := app.InventoryPayload{SchemaVersion: 1}
	for _, test := range []struct {
		name, digest string
		size         int
		render       func(app.InventoryPayload, string) ([]byte, error)
	}{
		{"html", "b1930fbb47706d5326913cc470b7bc4746c477b894bf7288ddb677f2b70de775", 3013, InventoryHTMLForVersion},
		{"pdf", "b1582386321add5decc26ff326aa1d84dcb5287436c093dfae68874c1228cf2a", 1166, InventoryPDFForVersion},
	} {
		t.Run(test.name, func(t *testing.T) {
			encoded, err := test.render(payload, "0.0.1-fixture")
			if err != nil || len(encoded) != test.size || fmt.Sprintf("%x", sha256.Sum256(encoded)) != test.digest {
				t.Fatalf("legacy view bytes changed: size=%d err=%v", len(encoded), err)
			}
		})
	}
}

func TestRetestViewsShowOnlyTheAuthenticatedReference(t *testing.T) {
	previous := report.PreviousReport{ManifestDigest: "sha256:" + strings.Repeat("a", 64), BundleSHA256: "sha256:" + strings.Repeat("b", 64)}
	payload := testPayload()
	before := payload.Components[0]
	for _, test := range []struct {
		name   string
		render func(app.InventoryPayload, string, report.PreviousReport) ([]byte, error)
	}{
		{"html", InventoryRetestHTMLForVersion}, {"pdf", InventoryRetestPDFForVersion},
	} {
		t.Run(test.name, func(t *testing.T) {
			encoded, err := test.render(payload, "0.0.1-fixture", previous)
			if err != nil {
				t.Fatal(err)
			}
			if !bytes.Contains(encoded, []byte(previous.ManifestDigest)) || !bytes.Contains(encoded, []byte(previous.BundleSHA256)) {
				t.Fatal("view omitted one authenticated parent digest")
			}
			lower := strings.ToLower(string(encoded))
			for _, forbidden := range []string{"verified parent", "trusted parent", "<script", "/javascript", "http://", "https://"} {
				if strings.Contains(lower, forbidden) {
					t.Fatal("static view invented dynamic trust or active content")
				}
			}
			if payload.Components[0].ID != before.ID || payload.Components[0].Identity != before.Identity {
				t.Fatal("rendering mutated current inventory")
			}
			for _, bad := range []report.PreviousReport{{ManifestDigest: previous.ManifestDigest}, {ManifestDigest: previous.ManifestDigest, BundleSHA256: `<script>fixture</script>`}} {
				if output, err := test.render(payload, "0.0.1-fixture", bad); err == nil || len(output) != 0 {
					t.Fatal("invalid reference produced a view")
				}
			}
		})
	}
}
